79:'勉強した時間を記録できる、無料のアプリだがね。ちなコーチもおすすめしとるでね。',
80:'<b>なんで大事なの？<\/b>　<a class="in" href="#q-typelist">タイプ別の一覧表<\/a>は、勉強した時間（0〜10時間、11〜20時間…）ごとに、やることが書いてあるでね。スタディプラスで合計の時間が分かると、「いま一覧表のどこにおって、次に何をしたらええか」がすぐ分かるがね。進めていくときの、道しるべになるでよ。ロードマップ（教科書の写真つき）にも「0時間〜3000時間」の目安があるで、あわせて見ると、もっと分かりやすなるでね。',
81:'時間が数字やグラフで見えると、積み上げてきたことが自信になるでね。週報の学習時間も、そのまま書けるがね。',
