84:'中1・中2・中3に分かれた本（『中1英語をひとつひとつわかりやすく。』など）ではのうて、中学3年分が1冊にまとまった本だがね。表紙に「もう一度」と「改訂版」が入っとるのが目印だでね。',
85:'<a class="in" href="https://app.the-online-class.com/lessons/oAOxYzNzQDI6I2Y" target="_top">ロードマップ<\/a>や<a class="in" href="https://app.the-online-class.com/lessons/ogM0EDMxUDI6I2Y" target="_top">一覧表<\/a>で「文法ドリル」って書いてあるのは、ぜんぶこの本のことだがね。',
86:'英語を読む力をつける「精読」用の本だがね。<a class="in" href="https://app.the-online-class.com/lessons/oAOxYzNzQDI6I2Y" target="_top">ロードマップ<\/a>のSTEP2「英語を読む」で使うでね。',
87:'「多読」の教材は本ではのうて、オンクラスの「<a class="in" href="https://app.the-online-class.com/learning_courses/oQDO2gDI6MGb" target="_top">2.英語を読む<\/a>」にあるでね。',
