160:'LINEの下に出とるメニューの「<a class="in" href="https://app.the-online-class.com/learning_courses/oQTM2gDI6MGb" target="_top">1.文法を学ぶ<\/a>」をタップするでね。',
161:'最初の「<a class="in" href="https://app.the-online-class.com/lessons/oQMyczM1QDI6I2Y" target="_top">はじめに<\/a>」の動画を見てちょう。進め方がぜんぶ分かるでね。',
162:'一回登録した人は「新規登録」ではのうて「ログイン」から入るでね。',
163:'パスワードのメールが来んときは、迷惑メールのフォルダを見てちょう。',
164:'それでも来んときは、登録したメールアドレスがちがうかもしれんでね。受講生LINEで知らせてちょう。',
165:'スマホでは出るか、見てみてちょう。',
166:'iPadは機種のしくみで、メニューが出んことがあるでね。',
167:'ページを「お気に入り」か「ホーム画面に追加」しとくと、すぐ開けるでね。',
168:'画面の右下（または右上）の「…」や共有のボタンから、「Safariで開く」「Chromeで開く」を選んでみてちょう。',
