170:'それでも見れんときは、使っとる機械（iPhone・Androidなど）を書いて、受講生LINEに送ってちょう。',
171:'動画の画面を、一回タップするでね。',
172:'画面に出る「CC」のマーク（字幕のボタン）を押すと、字幕が消えるでね。もう一回押すと、また出るがね。',
173:'「CC」が見つからんときは、歯車のマーク（設定）→「字幕」→「オフ」を選ぶでね。',
