176:'準備ができたら、LINEの「青い文字」（青色のボタン）を押してちょう。次の朝から音声が届くでね。',
177:'まず動画「【タイプ別】英語学習の進め方」で、自分がどのタイプかを確かめるでね。',
178:'次に資料（一覧表）で、自分のタイプの進め方を見るでね。今どこにおるか、次に何をするかが分かるがね。',
179:'一覧表は、勉強した時間ごとに分かれとるでね。時間は「<a class="in" href="#q-studyplus">スタディプラス<\/a>」で測ると、自分がどこにおるか分かるがね。',
180:'文字だけだと分かりにくいときは、「資料【ロードマップ】」を見てちょう。使う教科書の写真つきで、全体の流れがひと目で分かるでね。',
181:'下のボタンから、アプリを入れるでね（無料）。',
