55:'あてはまるもんをタップしたら、答えが開くで。受講生のみなさんから届いた質問、約1,300件をもとに作ったんよ。',
56:'ちなコーチと一緒に、大人が英語を学び直すスクールやで。',
57:'いろんな事情で、英語から離れてまう時期があっても大丈夫やで。今は思うようにでけへんでも、また始めたなったとき、いつでも帰ってこれる場所が、90プログラムやねん。<br>ここは、みなさんの場所や。同じように学ぶ仲間が、待ってるで。',
58:'毎月、ちなコーチがセミナーしてるねん。受講生やったら、だれでも、いつでも参加できるで。',
59:'学習の速さや進み具合は関係あらへんで。始めたばっかりの方も、気軽に参加してな。',
60:'どっちも大丈夫やで。',
61:'顔出しはおすすめやけど、決まりちゃうで。',
62:'それでも入られへんときは、受講生LINEにひとこと送ってな。',
63:'回によっては録画を出さへんこともあるねん。その回の案内を見てな。',
64:'3つの使い分けやで。',
65:'どの部屋も、自由に見て大丈夫やで。入ったばっかりの方も、遠慮せんとのぞいてみてな。',
66:'読むだけでもOKやで。みなさんの投稿から、やる気や勉強のヒントがぎょうさんもらえるねん。',
67:'よかったら、ほかの方の投稿読んで、スタンプも押してみてな。押すのは自由やけど、あなたのスタンプひとつが「見てるで」「一緒にがんばろな」っていうエールになって、だれかの「今日もがんばろ」につながるねん。',
68:'作り方の説明があるで。順番に進めたら大丈夫や。',
69:'申請フォーム送ってから24時間以内に、運営サポーターから申請が届くで。',
70:'スマホとパソコンで、やり方がちょっとちゃうねん。',
71:'<b>スタンプ・返信<\/b>：投稿にマウスを乗せたら、右側にスタンプ（にこにこマーク）や返信（矢印）のボタンが出るで。押して選んでな。',
72:'まちがえて付けたスタンプは、もう一回押したら消せるで。',
73:'勉強は「オンクラス」でするんやで。LINEは入口や。',
74:'LINEの中で開いた画面やと、動画が止まることがあるねん。',
75:'字幕は、見る人それぞれの設定やねん。自分で消せるで。',
76:'字幕消しても、ほかの人の画面は何も変わらへんで。',
77:'決まった開講日はあらへんで。「始めよか」て思た日がスタートや。',
78:'オンクラスの「<a class="in" href="https://app.the-online-class.com/learning_courses/oQTM2gDI6MGb" target="_top">1.文法を学ぶ<\/a>」→「はじめに」にあるで。',
79:'勉強した時間を記録できる、無料のアプリやで。ちなコーチもおすすめしてはるねん。',
80:'<b>なんで大事なん？<\/b>　<a class="in" href="#q-typelist">タイプ別の一覧表<\/a>は、勉強した時間（0〜10時間、11〜20時間…）ごとに、やることが書いてあるねん。スタディプラスで合計の時間が分かったら、「いま一覧表のどこにおって、次に何したらええか」がすぐ分かるで。進めていくときの、道しるべになるんや。ロードマップ（教科書の写真つき）にも「0時間〜3000時間」の目安があるから、あわせて見たら、もっと分かりやすなるで。',
81:'時間が数字やグラフで見えたら、積み上げてきたことが自信になるで。週報の学習時間も、そのまま書けるねん。',
82:'正確に測られへんでも大丈夫やで。毎日の学習を積み上げてる事実だけで、120点満点や。',
83:'『中学英語をもう一度ひとつひとつわかりやすく。改訂版』（学研）っていう本のことやで。これから買う方には、改訂版がおすすめや。',
84:'中1・中2・中3に分かれた本（『中1英語をひとつひとつわかりやすく。』など）やなくて、中学3年分が1冊にまとまった本やで。表紙に「もう一度」と「改訂版」が入ってるのが目印や。',
85:'<a class="in" href="https://app.the-online-class.com/lessons/oAOxYzNzQDI6I2Y" target="_top">ロードマップ<\/a>や<a class="in" href="https://app.the-online-class.com/lessons/ogM0EDMxUDI6I2Y" target="_top">一覧表<\/a>で「文法ドリル」って書いてあるんは、ぜんぶこの本のことやで。',
86:'英語を読む力をつける「精読」用の本やで。<a class="in" href="https://app.the-online-class.com/lessons/oAOxYzNzQDI6I2Y" target="_top">ロードマップ<\/a>のSTEP2「英語を読む」で使うねん。',
87:'「多読」の教材は本やなくて、オンクラスの「<a class="in" href="https://app.the-online-class.com/learning_courses/oQDO2gDI6MGb" target="_top">2.英語を読む<\/a>」にあるで。',
88:'オンクラスに「瞬間英作文 Q&amp;A一覧」があるで。',
89:'そこで見つからへんときは、Discordの「<a class="in" href="https://discord.com/channels/1214839485364305960/1389188765729165393" target="_top">質問部屋<\/a>」で聞いてな。',
90:'<a class="in" href="#q-drill">文法ドリル<\/a>で、英語の基本のルールが分かってから始めるんがおすすめやで。',
91:'深追いせんでも大丈夫やで。軽う調べて、先へ進も。',
92:'Part3の後半は、英語見て意味が分かったら、まずはOKやで。',
93:'この3段階を、ゆっくり上がっていったら十分やで。いきなり「速く・正しく」を目指したら、止まってもうて当然や。',
94:'読んだり聞いたりして「こういう意味やな」て分かったら、それで十分や。',
95:'それでも気になるときは、Discordの「<a class="in" href="https://discord.com/channels/1214839485364305960/1389188765729165393" target="_top">質問部屋<\/a>」で聞いてな。',
96:'挫折せえへん英語学習を身につけることが、ゴールやで。その先の目安は、外国の方と30分間、ストレスなく英会話ができる状態やで。',
97:'最初の90日は、1番の「文法の土台」をかためる期間やで。90日を過ぎても、仲間と学べる場所は、ずっとそのままやで。',
98:'順番は決まってるねん。最初の90日は「文法の土台」づくりや。',
99:'オンクラスの「1」「2」「3」を同時に進めんでも大丈夫やで。まずは「マスター講座＋文法ドリル」から始めるんや。',
100:'ちゃうねん。5〜8割わかったら、どんどん先へ進むで。',
101:'「森を見て、木を見る」がおすすめやで。',
102:'「1ページを100%にしてから」やなくて、全体をつかみながら、気になるところに少し時間かけるくらいが、ちょうどええバランスやで。',
103:'簡単すぎると思たら、次のレベルへ進んで大丈夫やで。',
104:'ノートとらんでも、英語の力はちゃんとのびるで。',
