160:'LINEの下に出てるメニューの「<a class="in" href="https://app.the-online-class.com/learning_courses/oQTM2gDI6MGb" target="_top">1.文法を学ぶ<\/a>」をタップするで。',
161:'最初の「<a class="in" href="https://app.the-online-class.com/lessons/oQMyczM1QDI6I2Y" target="_top">はじめに<\/a>」の動画見てな。進め方がぜんぶ分かるで。',
