47:'90日ば過ぎたら、どうなると？',
48:'91日目からは、日報ばどこに書くと？',
49:'スマホの画面の消えると音声の止まってしまう',
50:'自分の投稿だけばまとめて見たか',
51:'「きまぐれラジオ」ってなんね？',
52:'「こんなこと、やってみたか！」のあるときは？',
53:'オフ会やイベントのお知らせは、どこで見ると？',
54:'ちなコーチに直接連絡したか',
55:'あてはまるものばタップすると、答えの開くけんね。受講生のみなさんから届いた質問、約1,300件をもとに作ったとよ。',
56:'ちなコーチと一緒に、大人が英語ば学び直すスクールたい。',
57:'いろいろな事情で、英語から離れてしまう時期のあっても大丈夫やけんね。今は思うごとできんでも、また始めたくなったとき、いつでも帰ってこれる場所が、90プログラムなんよ。<br>ここは、みなさんの場所たい。同じように学ぶ仲間の、待っとるけんね。',
58:'毎月、ちなコーチがセミナーばしよるとよ。受講生なら、だれでも、いつでも参加できるけんね。',
59:'学習の速さや進み具合は関係なかよ。始めたばっかりの方も、気軽に参加してね。',
60:'どっちも大丈夫よ。',
61:'顔出しはおすすめやけど、決まりじゃなかよ。',
62:'それでも入れんときは、受講生LINEにひとこと送ってね。',
63:'回によっては録画ば出さんこともあるとよ。その回の案内ば見てね。',
64:'3つの使い分けたい。',
65:'どの部屋も、自由に見て大丈夫よ。入ったばっかりの方も、遠慮せんでのぞいてみてね。',
66:'読むだけでもOKよ。みなさんの投稿から、やる気や勉強のヒントのいっぱいもらえるけんね。',
67:'よかったら、ほかの方の投稿ば読んで、スタンプも押してみてね。押すとは自由やけど、あなたのスタンプひとつが「見とるよ」「一緒にがんばろうね」っていうエールになって、だれかの「今日もがんばろう」につながるとよ。',
68:'作り方の説明のあるけんね。順番に進めたら大丈夫よ。',
69:'申請フォームば送ってから24時間以内に、運営サポーターから申請の届くけんね。',
70:'スマホとパソコンで、やり方の少しちがうとよ。',
71:'<b>スタンプ・返信<\/b>：投稿にマウスば乗せると、右側にスタンプ（にこにこマーク）や返信（矢印）のボタンの出るとよ。押して選んでね。',
72:'まちがえて付けたスタンプは、もう一回押すと消せるけん。',
73:'勉強は「オンクラス」でするとよ。LINEは入口たい。',
74:'LINEの中で開いた画面やと、動画の止まることのあるとよ。',
75:'字幕は、見る人それぞれの設定やけん。自分で消せるとよ。',
76:'字幕ば消しても、ほかの人の画面は何も変わらんよ。',
77:'決まった開講日はなかよ。「始めよう」って思った日がスタートたい。',
78:'オンクラスの「<a class="in" href="https://app.the-online-class.com/learning_courses/oQTM2gDI6MGb" target="_top">1.文法を学ぶ<\/a>」→「はじめに」にあるけんね。',
79:'勉強した時間ば記録できる、無料のアプリたい。ちなコーチもおすすめしとるとよ。',
80:'<b>なんで大事なと？<\/b>　<a class="in" href="#q-typelist">タイプ別の一覧表<\/a>は、勉強した時間（0〜10時間、11〜20時間…）ごとに、やることの書いてあるとよ。スタディプラスで合計の時間の分かると、「いま一覧表のどこにおって、次に何ばすればよかか」がすぐ分かるけん。進めていくときの、道しるべになるとよ。ロードマップ（教科書の写真つき）にも「0時間〜3000時間」の目安のあるけん、あわせて見ると、もっと分かりやすくなるよ。',
81:'時間の数字やグラフで見えると、積み上げてきたことの自信になるとよ。週報の学習時間も、そのまま書けるけんね。',
82:'正確に測れんでも大丈夫よ。毎日の学習ば積み上げとる事実だけで、120点満点たい。',
83:'『中学英語をもう一度ひとつひとつわかりやすく。改訂版』（学研）っていう本のことたい。これから買う方には、改訂版がおすすめよ。',
84:'中1・中2・中3に分かれた本（『中1英語をひとつひとつわかりやすく。』など）じゃなくて、中学3年分が1冊にまとまった本たい。表紙に「もう一度」と「改訂版」の入っとるとが目印よ。',
85:'<a class="in" href="https://app.the-online-class.com/lessons/oAOxYzNzQDI6I2Y" target="_top">ロードマップ<\/a>や<a class="in" href="https://app.the-online-class.com/lessons/ogM0EDMxUDI6I2Y" target="_top">一覧表<\/a>で「文法ドリル」って書いてあるとは、ぜんぶこの本のことたい。',
86:'英語ば読む力ばつける「精読」用の本たい。<a class="in" href="https://app.the-online-class.com/lessons/oAOxYzNzQDI6I2Y" target="_top">ロードマップ<\/a>のSTEP2「英語を読む」で使うとよ。',
87:'「多読」の教材は本じゃなくて、オンクラスの「<a class="in" href="https://app.the-online-class.com/learning_courses/oQDO2gDI6MGb" target="_top">2.英語を読む<\/a>」にあるけんね。',
88:'オンクラスに「瞬間英作文 Q&amp;A一覧」のあるとよ。',
89:'そこで見つからんときは、Discordの「<a class="in" href="https://discord.com/channels/1214839485364305960/1389188765729165393" target="_top">質問部屋<\/a>」で聞いてね。',
90:'<a class="in" href="#q-drill">文法ドリル<\/a>で、英語の基本のルールの分かってから始めるとがおすすめよ。',
91:'深追いせんでも大丈夫よ。軽く調べて、先へ進もうね。',
92:'Part3の後半は、英語ば見て意味の分かれば、まずはOKよ。',
93:'この3段階ば、ゆっくり上がっていけば十分よ。いきなり「速く・正しく」ば目指すと、止まってしまって当然たい。',
94:'読んだり聞いたりして「こういう意味たいね」って分かれば、それで十分よ。',
95:'それでも気になるときは、Discordの「<a class="in" href="https://discord.com/channels/1214839485364305960/1389188765729165393" target="_top">質問部屋<\/a>」で聞いてね。',
96:'挫折せん英語学習ば身につけることが、ゴールよ。その先の目安は、外国の方と30分間、ストレスなく英会話のできる状態たい。',
97:'最初の90日は、1番の「文法の土台」ばかためる期間よ。90日ば過ぎても、仲間と学べる場所は、ずっとそのままやけん。',
98:'順番は決まっとるとよ。最初の90日は「文法の土台」づくりたい。',
99:'オンクラスの「1」「2」「3」ば同時に進めんでも大丈夫よ。まずは「マスター講座＋文法ドリル」から始めるとよ。',
100:'ううん。5〜8割わかれば、どんどん先へ進むとよ。',
101:'「森ば見て、木ば見る」がおすすめよ。',
102:'「1ページば100%にしてから」じゃなくて、全体ばつかみながら、気になるところに少し時間ばかけるくらいが、ちょうどよかバランスたい。',
103:'簡単すぎると感じたら、次のレベルへ進んで大丈夫よ。',
104:'ノートばとらんでも、英語の力はちゃんとのびるけんね。',
105:'おすすめはアプリたい。',
