734:'<b>問題なら解ける<\/b>：ドリルの問題は解けるばってん、会話や瞬間英作文ではパッと出てこん。',
735:'<b>自然に使える<\/b>：説明ば思い出さんでも、会話や瞬間英作文で使える。',
736:'<b>人に教えられる<\/b>：なんでそうなるとかば説明できる。ここは最後のゴールで、時間ばかけて自然にたどりつくところたい。',
737:'③から④に近づくときに、瞬間英作文の大きな力になるとよ。瞬間英作文でつまずいたら、文法ドリルに戻ればOK。行ったり来たりしながら身についていくけん。',
738:'瞬間英作文の口から出てこん・何回くり返せばよか？',
