741:'必ず声に出してね。頭の中だけでやるより、ずっと身につくけん。',
742:'1つの項目（10問）は、1回10〜15分くらいで区切るとよ。1回で100％ば目指さんで、何日かに分けてくり返すと。',
743:'ちょっとずつ区切って何周かくり返して、8割くらい言えるようになったら、次へ進んで大丈夫よ。',
744:'瞬間英作文は「口と頭の筋トレ」たい。回数ば重ねるほど、必ず口の慣れてくるけん。',
745:'瞬間英作文の whose・of which が、どげんしても分からん',
746:'たくさんの人のつまずくところよ。文法ドリルには、このための回のなかと。',
747:'2026年2月22日のセミナー（関係代名詞・関係副詞）で、ちなコーチがくわしく解説しとるよ。オンクラスの「英語セミナー アーカイブ一覧」から見らるっけん。',
748:'Part3の後半は、まずは「英語ば見て意味の分かればOK」たい。ゆっくり、階段ばのぼるごと進めていこうや。',
