751:'番外編（前置詞セミナー・助動詞セミナーなど）は、どれも60分ばこえる長か動画たい。週末とか時間のとるるときに、気になるテーマから見れば十分よ。',
752:'90audioの届く時間（朝7時）ば変えたか',
753:'届く時間はみんないっしょの設定やけん、一人ずつ変えることはできんとよ。',
754:'朝早く出かける人は、前の日に届いた音声ば次の朝に聞くごと、1日ずらして進めるとも、おすすめよ。通知は切っとって大丈夫たい。',
755:'前から使いよる本や、ほかの教材ば使ってもよか？',
756:'「文法 → 読む → 聞く → 話す」の順番のくずれんなら、使って大丈夫よ。',
757:'「この本も読みたか」て気持ちは大事にしてね。ただ、今のステップの学習（文法ドリルや瞬間英作文など）が中心になるごと、時間ば調整しながら進めてね。',
758:'車の運転中や家事の間に、聞けるもんはある？',
759:'あるよ。耳と頭の空いとる時間は、音声の学習にぴったりたい。',
760:'文法ドリルの音声アプリ「マイオトモ」や、瞬間英作文アプリの自動再生（設定で「自動再生」ばON）がおすすめよ。',
