835:'彼の言ったことば、あとから自分が人に伝えよる文やけんたい。',
836:'迷ったら、その人のほんなこつ言ったセリフば思い浮かべてみて。',
837:'that や、関係代名詞の which・whom は、はぶいてもよかと？',
838:'I think (that) 〜 の that や、「〜が…する（名詞）」の which・whom は、はぶくことのできるとよ。会話では、はぶくことのとても多かよ。',
839:'名詞ば説明する言葉の1つだけのときは名詞の前（the sleeping baby）、長かときは名詞の後ろ（the baby sleeping in the car）に置くとよ。',
840:'90日目（Day90）の日は、なんばすると？',
841:'Day90の90audioば聞いたら、いつもの「90audio_アウトプット」の部屋に、ちなコーチへのメッセージば送ろうや。',
