22:'「究極の英語リーディング」って、なんなのさ？',
23:'瞬間英作文で「なしてこの答えになるのさ？」って思ったら',
24:'瞬間英作文は、いつから始めたらいいべか？',
25:'瞬間英作文で、知らない単語が出てきたら？',
26:'瞬間英作文のPart3がなまらむずかしい',
27:'むずかしい文法が出てきて、分かんないんだわ',
29:'何から、どの順番でやったらいいべか？',
30:'文法ドリル（『中学英語をもう一度ひとつひとつわかりやすく。』の本）は、完ぺきにしてから次へ進むのかい？',
31:'文法ドリルの2周目は、どうやって進めたらいいべか？',
32:'簡単すぎる・もう分かってるところは？',
33:'ノートはとったほうがいいのかい？',
36:'リーディング（読む）は、どう進めるのさ？',
37:'リスニング（聞く）は、どう進めるのさ？',
38:'発音の練習は、いつするのさ？',
39:'映画やドラマで、英語を楽しみたいんだわ',
