57:'いろんな事情で、英語から離れてしまわはる時期があっても大丈夫どす。今は思うようにできひんでも、また始めたなったとき、いつでも帰ってこられる場所が、90プログラムどすえ。<br>ここは、みなさんの場所。おんなじように学んではる仲間が、待ってはります。',
