67:'よかったら、ほかの方の投稿を読んで、気持ちのマーク（スタンプ）も押してみてください。押すのは自由ですが、あなたのスタンプひとつが「見てるよ」「一緒にがんばろう」というエールになって、だれかの「今日もがんばろう」につながります。',
