133:'セミナーの案内は、Discordの「<a class="in" href="https://discord.com/channels/1214839485364305960/1249989567998590977" target="_top">セミナー／イベント<\/a>」の部屋に出ます。お知らせ（通知）が来たら、見てみてください。',
134:'当日出られなくても大丈夫です。あとで録画（アーカイブ）が見られるので、安心してください。',
