150:'できたら、案内の用紙（フォーム）で、Discordでの自分の名前（ユーザー名）を送ってください。24時間以内に、運営サポーターから友だちのお誘い（申請）が届きます。',
151:'来ないときは、Discordの虫めがね（検索）で <code>shizuka074<\/code> と入れて、ご自分から友だちに追加してください。',
