153:'分からないときは、自分のページ（プロフィール画面）の写真（スクリーンショット）を、受講生LINEに送ってください。',
154:'<b>スタンプ（気持ちのマーク）<\/b>：投稿を指でしばらく押したまま（長押し）にして、出てきた絵のマークから選びます。もう付いているマークを押すと、同じものを付けられます。',
155:'<b>返信（返事）<\/b>：投稿を指でしばらく押したまま（長押し）にして、「返信」を選びます。だれへの返事か分かるので、話がつながります。',
156:'<b>呼びかけ<\/b>：文字を書くところに「@」と、相手の名前の最初の文字を打つと、名前の候補が出ます。選ぶと、相手にお知らせが届きます。',
157:'LINEに届いている「青い文字」（青色のボタン）は、もう押しましたか？',
